{
  "findings": [
    {
      "check_id": "CKV_GCP_11",
      "title": "Legacy ABAC enabled",
      "resource": "google_container_cluster.k8sexample",
      "severity": "CRITICAL",
      "explanation": "Legacy ABAC (Attribute-Based Access Control) is enabled, which is a deprecated and insecure access control mechanism. It should be disabled to enforce RBAC (Role-Based Access Control) for better security."
    },
    {
      "check_id": "CKV_GCP_10",
      "title": "Kubernetes alpha features enabled",
      "resource": "google_container_cluster.k8sexample",
      "severity": "HIGH",
      "explanation": "Enabling Kubernetes alpha features can introduce instability and security risks as these features are not production-ready."
    },
    {
      "check_id": "CKV_GCP_6",
      "title": "Basic authentication enabled",
      "resource": "google_container_cluster.k8sexample",
      "severity": "HIGH",
      "explanation": "Basic authentication using username and password is enabled, which is insecure. It should be disabled to prevent unauthorized access."
    }
  ],
  "patched_code": "resource "google_container_cluster" "k8sexample" {
  name               = "${var.vault_user}-k8s-cluster"
  description        = "example k8s cluster"
  zone               = "${var.gcp_zone}"
  initial_node_count = "${var.initial_node_count}"

  enable_kubernetes_alpha = false
  enable_legacy_abac       = false

  master_auth {
    username = ""
    password = ""
    client_certificate_config {
      issue_client_certificate = true
    }
  }

  node_config {
    machine_type = "${var.node_machine_type}"
    disk_size_gb = "${var.node_disk_size}"
    oauth_scopes = [
      "https://www.googleapis.com/auth/compute",
      "https://www.googleapis.com/auth/devstorage.read_only",
      "https://www.googleapis.com/auth/logging.write",
      "https://www.googleapis.com/auth/monitoring"
    ]
  }
}",
  "fix_summary": "Disabled legacy ABAC and Kubernetes alpha features to improve security and stability. Removed basic authentication by clearing the username and password fields in the master_auth block."
}
